try{$pdo=ps23_db();ps23_ensure($pdo);$ctx=ps23_context($pdo);$set=ps23_settings($pdo,$ctx['organization_id']);if(empty($set['storefront_enabled']))throw new RuntimeException('The product portal is temporarily unavailable.');$rows=ps23_catalog($pdo,$ctx['organization_id'],$q,$category);$cats=ps23_categories($pdo,$ctx['organization_id']);}catch(Throwable $e){$error=$e->getMessage();}
